    private static Fixture running,retained;
    public static void run(GameController game){require(running==null&&retained==null,"exclusive fixture");running=new Fixture(game);}
    public static void stopProbe(GameController game){require(running==null&&retained==null,"exclusive real-stop fixture");running=new Fixture(game);running.stopMode=true;}
    public static void cleanup(GameController game){var f=Objects.requireNonNull(retained,"retained actual native stop fixture");try{require(!game.items().currentEpoch(f.epoch)&&f.bullets().isEmpty()&&f.created.stream().filter(ShulkerBullet.class::isInstance).allMatch(Entity::isRemoved)&&!f.owner.getAttribute(Attributes.MOVEMENT_SPEED).hasModifier(LbcShulkerArmor.SPEED)&&(Integer)read(f.service,"phase")==0,"actual match stop removes tracked native shell, full-set speed and phase: epoch="+game.items().currentEpoch(f.epoch)+", bullets="+f.bullets().size()+", speed="+f.owner.getAttribute(Attributes.MOVEMENT_SPEED).hasModifier(LbcShulkerArmor.SPEED)+", phase="+read(f.service,"phase"));}finally{try{f.close();}finally{retained=null;}}SkyWars2.LOGGER.info("[check] PASS shulker-armor-cleanup");}
    public static void tick(GameController game){if(running==null)return;try{if(running.preparing){running.prepare();if(!running.preparing&&running.stopMode){running.created.addAll(running.bullets());retained=running;running=null;SkyWars2.LOGGER.info("[check] PASS shulker-armor-stop-probe");}return;}if(running.step()){running.close();running=null;SkyWars2.LOGGER.info("[check] PASS shulker-armor (original four leaves/root/pre/full and normal/Ultra reforge; actual worn bonus/noarrows; native shell collision/current owner/team; real jump/environmental/shield criterion; beacon/roles; native2/200tick scheduler; scoped restore)");}}catch(Throwable error){boolean probe=running.stopMode;try{running.close();}catch(Throwable cleanup){error.addSuppressed(cleanup);}finally{running=null;}SkyWars2.LOGGER.error("[check] FAIL "+(probe?"shulker-armor-stop-probe":"shulker-armor"),error);}}
